<?php
namespace App\Http\Controllers;
use App\Models\{Content,Inquiry};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{Auth,DB,Hash};
use Illuminate\Support\Str;
class AdminController extends Controller {
 const CONTENT=['banners','pages','services','projects','testimonials','before_after_galleries'];
 const TABLES=['banners','pages','services','projects','testimonials','before_after_galleries','project_categories','project_images','seo_metadata','website_settings','media_assets','inquiries'];
 public function login(Request $r){$data=$r->validate(['email'=>'required|email','password'=>'required|string']);if(Auth::attempt($data+['is_admin'=>true])){$r->session()->regenerate();return redirect('/admin');}return back()->withErrors(['email'=>'The login details could not be verified.'])->onlyInput('email');}
 public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/admin/login');}
 private function query(string $module){abort_unless(in_array($module,self::TABLES,true),404);return in_array($module,self::CONTENT,true)?Content::for($module)->newQuery():DB::table($module);}
 public function index(Request $r,string $module='dashboard'){$rows=null;if($module!=='dashboard'&&$module!=='profile'){$q=$this->query($module);if($r->filled('q')){$column=match($module){'inquiries'=>'name','website_settings'=>'key','media_assets'=>'alt','project_images'=>'alt',default=>'title'};$q->where($column,'like','%'.$r->string('q').'%');}if($module==='inquiries'&&$r->filled('status'))$q->where('status',$r->string('status'));$rows=$q->orderByDesc('id')->paginate(15)->withQueryString();}return view('admin.index',['module'=>$module,'rows'=>$rows,'modules'=>self::TABLES,'total'=>Inquiry::count(),'new'=>Inquiry::where('status','new')->count(),'recent'=>Inquiry::latest()->limit(5)->get()]);}
 public function edit(string $module,?int $id=null){abort_if($module==='inquiries',404);$this->query($module);$record=$id?$this->query($module)->where('id',$id)->first():null;abort_if($id&&!$record,404);return view('admin.edit',compact('module','record')+['modules'=>self::TABLES,'categories'=>DB::table('project_categories')->get(),'projects'=>Content::for('projects')->get()]);}
 public function save(Request $r,string $module,?int $id=null){abort_if($module==='inquiries'&&!$id,404);if($module==='seo_metadata')$r->merge(['path'=>trim((string)$r->input('path'),'/')?:'/']);$q=$this->query($module);if($id)abort_unless((clone $q)->where('id',$id)->exists(),404);
 if(in_array($module,self::CONTENT,true)){$data=$r->validate(['title'=>'required|string|max:200','slug'=>'required|alpha_dash|max:200|unique:'.$module.',slug'.($id?','.$id:''),'description'=>'nullable|string|max:2000','content'=>'nullable|string|max:50000','location'=>'nullable|string|max:200','project_category_id'=>'nullable|exists:project_categories,id','image'=>'nullable|string|max:500','secondary_image'=>'nullable|string|max:500','sort_order'=>'required|integer|min:0','published'=>'nullable|boolean','is_sample'=>'nullable|boolean']);if($module!=='projects')unset($data['project_category_id']);$data['published']=$r->boolean('published');$data['is_sample']=$r->boolean('is_sample');}
 else {$rules=match($module){'project_categories'=>['title'=>'required|string|max:200','slug'=>'required|alpha_dash|max:200|unique:project_categories,slug'.($id?','.$id:'')],'website_settings'=>['key'=>'required|alpha_dash|max:100|unique:website_settings,key'.($id?','.$id:''),'value'=>'nullable|string|max:10000'],'seo_metadata'=>['path'=>'required|string|max:200|unique:seo_metadata,path'.($id?','.$id:''),'title'=>'required|string|max:200','description'=>'required|string|max:500'],'project_images'=>['project_id'=>'required|exists:projects,id','alt'=>'required|string|max:200','path'=>'required|string|max:500','sort_order'=>'required|integer|min:0'],'media_assets'=>['alt'=>'required|string|max:200','upload'=>'required|image|mimes:jpg,jpeg,png,webp|max:5120|dimensions:max_width=8000,max_height=8000'],'inquiries'=>['status'=>'required|in:new,contacted,consultation,closed'],default=>[]};$data=$r->validate($rules);}
 foreach(['image','secondary_image','path'] as $field)if(!empty($data[$field]))abort_unless(Str::startsWith($data[$field],['/storage/','/images/','https://images.unsplash.com/']),422,'Use a local media path or an Unsplash image URL.');
 if($module==='media_assets'){$file=$r->file('upload');$data=['alt'=>$data['alt']]+app(\App\Services\ImageOptimizer::class)->store($file);}
 $data['updated_at']=now();if($id)$q->where('id',$id)->update($data);else{$data['created_at']=now();$q->insert($data);}return redirect('/admin/'.$module)->with('success','Changes saved.');}
 public function delete(string $module,int $id){$q=$this->query($module);abort_if($module==='inquiries',403);$q->where('id',$id)->delete();return back()->with('success','Entry removed.');}
 public function profile(Request $r){$data=$r->validate(['name'=>'required|string|max:100','email'=>'required|email|unique:users,email,'.$r->user()->id,'current_password'=>'required|current_password','password'=>'nullable|confirmed|min:12']);$user=$r->user();$user->name=$data['name'];$user->email=$data['email'];if(!empty($data['password']))$user->password=Hash::make($data['password']);$user->save();return back()->with('success','Profile updated.');}
}
